#include <stdio.h>

int check(long long N, long long K) {
    long long n = N;
    int steps = 0;
    while (n != 1 && steps < 1000000) {
        if (n <= 0) return 0;
        if (n % K == 0) {
            n = n / K;
        } else {
            n = n - K;
        }
        steps++;
        if (n <= 0) return 0;
    }
    return n == 1;
}

