typedef long long ll;

ll count_divisors(ll x) {
    ll cnt = 0;
    for (ll d = 1; d * d <= x; d++) {
        if (x % d == 0) {
            cnt++;
            if (d * d != x) cnt++;
        }
    }
    return cnt;
}

int main(void) {
    ll N;
    scanf("%lld", &N);

    ll ans = 0;

    /* Case 1:
       K divides N at least once.
       Let M be N after removing all factors K from N.
       Then K is valid iff M % K == 1.
       This happens exactly for divisors K of N with K >= 2 satisfying that condition.
    */
    for (ll d = 2; d * d <= N; d++) {
        if (N % d == 0) {
            ll k1 = d;
            ll x = N;
            while (x % k1 == 0) x /= k1;
            if (x % k1 == 1) ans++;

            ll k2 = N / d;
            if (k2 != k1) {
                x = N;
                while (x % k2 == 0) x /= k2;
                if (x % k2 == 1) ans++;
            }
        }
    }
    /* K = N is always valid in case 1 */
    ans++;

    /* Case 2:
       K never divides N initially. Then only subtraction happens.
       We reach 1 iff N % K == 1, i.e. K is a divisor of N-1, with K >= 2.
       Number of such K = number of divisors of N-1 minus 1 (excluding 1).
    */
    ans += count_divisors(N - 1) - 1;

    printf("%lld\n", ans);
    return 0;
}

