using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 N;
    cin >> N;

    auto divisors = [](int64 x) {
        vector<int64> d;
        for (int64 i = 1; i * i <= x; ++i) {
            if (x % i == 0) {
                d.push_back(i);
                if (i * i != x) d.push_back(x / i);
            }
        }
        return d;
    };

    int64 ans = 0;

    // Case 1: K divides N initially.
    // Let N = K^a * m, where m % K != 0.
    // After dividing as much as possible, we get m.
    // Then we need m % K == 1 so repeated subtraction reaches 1.
    for (int64 k : divisors(N)) {
        if (k == 1) continue;
        int64 x = N;
        while (x % k == 0) x /= k;
        if (x % k == 1) ++ans;
    }

    // Case 2: K does not divide N initially.
    // Then only subtraction happens, so we need N % K == 1.
    // Such K are exactly divisors of N-1 greater than 1.
    for (int64 k : divisors(N - 1)) {
        if (k != 1) ++ans;
    }

    cout << ans << '\n';
    return 0;
}

