public class Main {
    static List<Long> divisors(long x) {
        List<Long> res = new ArrayList<>();
        for (long i = 1; i * i <= x; i++) {
            if (x % i == 0) {
                res.add(i);
                if (i * i != x) res.add(x / i);
            }
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long N = Long.parseLong(br.readLine().trim());

        long ans = 0;

        // Case 1:
        // K divides N at least once. Remove all factors of K from N.
        // Let remaining value be m. Then the process ends at 1 iff m % K == 1.
        for (long k : divisors(N)) {
            if (k == 1) continue;
            long x = N;
            while (x % k == 0) x /= k;
            if (x % k == 1) ans++;
        }

        // Case 2:
        // K does not divide N initially. Then we only subtract K.
        // To end at 1, we need N % K == 1.
        // Also K must not divide N, so these are exactly divisors of N-1 excluding 1,
        // except K=1 is not allowed. No overlap with Case 1 for K>=2.
        for (long k : divisors(N - 1)) {
            if (k >= 2) ans++;
        }

        System.out.println(ans);
    }
