def get_divisors(n):
    res = set()
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            res.add(i)
            res.add(n // i)
    res.add(n)
    return res

def solve():
    N = int(input().strip())
    ans = set()
    # K = N always works
    ans.add(N)
    # Check divisors of N
    for K in get_divisors(N):
        if K == 1:
            continue
        m = N
        while m % K == 0:
            m //= K
        if m % K == 1:
            ans.add(K)
    # Check divisors of N-1
    if N > 2:
        for K in get_divisors(N - 1):
            if K == 1:
                continue
            if (N % K) == 1:
                ans.add(K)
    print(len(ans))

