def reaches_one(initial_N, K):
    N = initial_N
    seen = set()
    while N != 1:
        if N in seen or N > initial_N * 2:  # cycle detection
            return False
        seen.add(N)
        if N % K == 0:
            N = N // K
        else:
            N = N - K
        if N <= 0:
            return False
    return True

